<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api,type ApiResponse}from'@whaashop/shared';interface Category{id?:number;parentId?:number;parentName?:string;name:string;sortOrder:number;enabled:boolean}const rows=ref<Category[]>([]),dialog=ref(false),form=reactive<Category>({name:'',sortOrder:0,enabled:true});const roots=computed(()=>rows.value.filter(v=>!v.parentId));const displayRows=computed(()=>roots.value.flatMap(root=>[root,...rows.value.filter(v=>v.parentId===root.id)]));async function load(){rows.value=(await api.get<ApiResponse<Category[]>>('/admin/categories')).data.data}function edit(v?:Category){Object.assign(form,v??{id:undefined,parentId:undefined,parentName:undefined,name:'',sortOrder:0,enabled:true});dialog.value=true}async function save(){if(form.id)await api.put(`/admin/categories/${form.id}`,form);else await api.post('/admin/categories',form);dialog.value=false;ElMessage.success('分类已保存');load()}async function remove(id:number){await ElMessageBox.confirm('确认删除该分类？','提示');await api.delete(`/admin/categories/${id}`);ElMessage.success('已删除');load()}onMounted(load)</script>
<template><div class="panel"><div class="toolbar"><div><h2>商品分类管理</h2><p style="margin:6px 0 0;color:#7b8ca5">父子分类分层展示，商品可归属到具体子分类</p></div><el-button type="primary" @click="edit()">新增分类</el-button></div><el-table :data="displayRows" row-key="id"><el-table-column prop="id" label="ID" width="90"/><el-table-column label="分类名称" min-width="220"><template #default="s"><span :style="{paddingLeft:s.row.parentId?'28px':'0',fontWeight:s.row.parentId?'500':'700'}"><span v-if="s.row.parentId" style="color:#9aa9bc;margin-right:8px">└</span>{{s.row.name}}</span><el-tag v-if="!s.row.parentId" size="small" style="margin-left:10px">父分类</el-tag></template></el-table-column><el-table-column label="父分类" min-width="150"><template #default="s"><span>{{s.row.parentName||'顶级分类'}}</span></template></el-table-column><el-table-column prop="sortOrder" label="排序" width="100"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="form.id?'编辑分类':'新增分类'" width="480"><el-form label-width="90"><el-form-item label="分类名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="父分类"><el-select v-model="form.parentId" clearable placeholder="不选择则为顶级分类" style="width:100%"><el-option v-for="c in roots.filter(v=>v.id!==form.id)" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
